fast_pseudocode:
@triton.autotune(configs=[Config({'XBLOCK': 1024}, num_warps=8), ...], key=['xnumel'])
@triton.jit
def kernel(... XBLOCK: tl.constexpr):
    ...

# CORRECT: grid adapts to whichever XBLOCK autotune selects
grid = lambda meta: (triton.cdiv(xnumel, meta['XBLOCK']),)
kernel[grid](... xnumel)  # no XBLOCK kwarg needed

